'use strict';
let app, project, page='brief', dirty=false, areaIndex=0, roomIndex=0, npcIndex=0, questIndex=0, templateIndex=0, report=null, proposal=null, previousDraft=null, generating=false;
let missionController=null,analysisController=null;
const $=s=>document.querySelector(s);
const clone=o=>JSON.parse(JSON.stringify(o));
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHtml;
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':app.csrf},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
let timer;function notify(message,error=false){$('#toast').textContent=message;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,error?18000:6000);}
async function task(control,fn){
 const relabel=control?.tagName==='BUTTON',label=relabel?control.textContent:null,disabled=control?.disabled;
 // Replacing a select's text removes its options and clears the pending value.
 if(control){control.disabled=true;if(relabel)control.textContent='Working…';}
 try{await fn();}catch(e){notify(e.message,true);}finally{if(control){control.disabled=disabled;if(relabel)control.textContent=label;}}
}
function value(path){return path.split('.').reduce((o,k)=>o[k],project);}
function field(label,path,type='text',options=[]){const v=value(path);let html;
 if(type==='textarea')html=`<textarea data-field="${path}">${E(v)}</textarea>`;
 else if(type==='select')html=`<select data-field="${path}">${options.map(o=>{const [id,name]=Array.isArray(o)?o:[o,o];return `<option value="${E(id)}" ${String(v)===String(id)?'selected':''}>${E(name)}</option>`;}).join('')}</select>`;
 else if(type==='checkbox')return `<label class="check"><input type="checkbox" data-field="${path}" ${v?'checked':''}>${E(label)}</label>`;
 else html=`<input data-field="${path}" type="${type}" value="${E(v)}" ${type==='number'?'step="1"':''} ${path==='module_name'?'maxlength="64" pattern="[a-z][a-z0-9_]{0,63}"':''}>`;
 if(path==='module_name')html+='<small class="hint">Up to 64 lowercase letters, digits or underscores, starting with a letter; omit .mod.</small>';
 return `<label class="field"><span>${E(label)}</span>${html}</label>`;
}
function change(){if(project.asset_geometry){const assets=new Set((project.custom_assets||[]).map(a=>a.id));project.asset_geometry=Object.fromEntries(Object.entries(project.asset_geometry).filter(([k])=>assets.has(k)));}if(project.object_positions){const ids=new Set([...(project.furnishings||[]),...(project.custom_placements||[])].map(f=>f.id));project.object_positions=project.object_positions.filter(p=>ids.has(p.id));}dirty=true;report=null;$('#saveState').textContent='Unsaved draft';}
function roomOptions(){return project.areas.flatMap(a=>a.rooms.map(r=>[r.id,a.name+' / '+r.name]));}
function questOptions(empty='Always available'){return [['',empty],...project.quests.map(q=>[q.id,q.name])];}
function confirmRemoval(name,detail='This removes it from the draft. Save the project to keep the change.'){
 return window.confirm('Remove '+name+'?\n\n'+detail);
}
function removalAction(name){
 const selected={deleteArea:()=>area()?.name,deleteRoom:()=>selectedRoom()?.name,deleteNPC:()=>project?.npcs?.[npcIndex]?.name,deleteQuest:()=>project?.quests?.[questIndex]?.name};
 if(Object.hasOwn(selected,name))return selected[name]()||'the selected item';
 const index=Number(name.split('_').at(-1));
 if(name.startsWith('remove_reference_'))return area()?.references?.[index]?.name||'this floor-plan reference';
 if(name.startsWith('remove_custom_'))return project.custom_placements?.[index]?.name||'this furnishing';
 if(name.startsWith('removeOpening_'))return (selectedRoom()?.openings?.[index]?.side||'this')+' wall opening';
 if(name.startsWith('removePlatform_'))return selectedRoom()?.platforms?.[index]?.name||'this platform and its stairs';
 if(name.startsWith('removeCarpet_'))return selectedRoom()?.carpets?.[index]?.name||'this carpet';
 if(name==='nativeGeometry')return 'the measured walls, room dimensions, openings, platforms and carpets from this area';
 if(name==='removeCourtyard')return 'this area’s generated courtyard walls, paving and paths';
 if(name.startsWith('key_remove_'))return 'the saved '+name.split('_').at(-1)+' API key';
 return '';
}
function questSummary(q){const names=Object.fromEntries(q.steps.map(s=>[s.id,s.name]));const next=id=>E(id?(names[id]||id):'Complete');return q.steps.map(s=>E(s.name)+' → '+(s.kind==='choice'?s.choices.map(c=>E(c.label)+': '+next(c.next)).join(' / '):next(s.next))).join('<br>');}
function npcOptions(empty='Start automatically'){return [['',empty],...project.npcs.map(n=>[n.id,n.name])];}
function id(prefix){let i=1;const raw=JSON.stringify(project);while(raw.includes('"'+prefix+i+'"'))i++;return prefix+i;}
function area(){return project.areas[areaIndex];}
function selectedRoom(){return area()?.rooms[roomIndex];}
function meta(){return {areas:project.areas.length,rooms:project.areas.reduce((n,a)=>n+a.rooms.length,0),characters:project.npcs.length,encounters:project.encounters.length,quests:project.quests.length};}
function syncNavigation(){
 document.querySelector('nav[aria-label="Authoring workflow"]').hidden=false;
 document.querySelectorAll('nav [data-page]').forEach(b=>{const section=b.dataset.page,active=page===section;b.classList.toggle('active',active);b.hidden=!project?!['analyser','settings','guardrails'].includes(section):project.design_mode==='area'&&['brief','quests'].includes(section);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 const areaNav=$('#areaNavigation');if(areaNav)areaNav.hidden=page!=='world'||!project;
 document.querySelector('nav [data-page="world"]')?.setAttribute('aria-expanded',String(page==='world'&&!!project));
}
function scrollWorkspaceTop(){const main=document.querySelector('main');main?.scrollTo({top:0,behavior:'instant'});window.scrollTo({top:0,behavior:'instant'});main?.focus({preventScroll:true});}
function navigate(section){page=section;render();scrollWorkspaceTop();}
function renderHeader(){if(!project)return;syncNavigation();['#saveProject','#deleteProject','#reviewProject'].forEach(s=>$(s).disabled=generating||designBusy);$('#projectTitle').textContent=project.title;$('#saveState').textContent=dirty?'Unsaved draft':'Saved';$('#stats').innerHTML=Object.entries(meta()).map(([k,n])=>`<div class="stat"><strong>${n}</strong><span>${k}</span></div>`).join('');}
function projectList(){const current=project?.id,list=app.projects.filter(p=>p.schema_version===2),select=$('#projectSelect');select.innerHTML=list.map(p=>`<option value="${E(p.id)}">${E(p.title)}</option>`).join('')||'<option value="">No saved projects</option>';select.disabled=!list.length;if(current)select.value=current;}
async function load(ident){project=(await api('/api/project?id='+encodeURIComponent(ident))).project;if(project.schema_version!==2)throw Error('This is a legacy companion project. Use the original companion page for that file.');dirty=false;report=null;previousDraft=null;proposal=null;areaIndex=roomIndex=npcIndex=questIndex=templateIndex=0;page=project.design_mode==='area'?'world':'brief';render();}
async function save(){project=(await api('/api/project/save',{project})).project;dirty=false;app.projects=(await api('/api/state')).projects;projectList();renderHeader();notify('Adventure project saved.');}
function emptyWorkspace(){
 $('#projectTitle').textContent='Your Module Studio';$('#saveState').textContent='No project selected';$('#stats').innerHTML='';
 ['#saveProject','#deleteProject','#reviewProject'].forEach(s=>$(s).disabled=true);
 syncNavigation();
 if(page==='guardrails'){$('#workspace').innerHTML=guardrailsPanel();bindSafety();loadUsage();return;}if(page==='settings'){$('#workspace').innerHTML=settings();bind();bindProviderSetup();return;}
 $('#workspace').innerHTML='<div class="card"><h2>No projects yet</h2><p>Create a new area or adventure, or import a saved project to begin.</p><div class="actions"><button id="emptyNewProject" class="primary">Create project</button><button id="emptyImportProject">Import project</button></div></div>';
 $('#emptyNewProject').onclick=()=>$('#newProject').click();$('#emptyImportProject').onclick=()=>$('#importProject').click();
}
function requestProjectDeletion(){
 if(!project)return;
 if(generating||designBusy||$('#saveProject').disabled){notify('Wait for the current project operation to finish.',true);return;}
 // The selected saved ID can differ from an ID edited in an unsaved draft.
 const ident=$('#projectSelect').value,saved=app.projects.find(p=>p.id===ident);
 if(!saved){notify('Choose a saved project to delete.',true);return;}
 modal(`<h2>Delete ${E(saved.title)}?</h2><p>This permanently removes <strong>${E(saved.id)}.json</strong>, including its saved story, area designs and embedded floor plans, from this computer. This cannot be undone.</p>${dirty?'<p class="notice">Your unsaved edits to this project will also be discarded.</p>':''}<p class="hint">Exported modules, generated build copies, import backups, downloaded asset packs and API settings remain available.</p><div class="actions"><button id="cancelProjectDeletion">Cancel</button><button id="confirmProjectDeletion" class="danger">Delete project permanently</button></div><p id="deleteProjectStatus" role="status"></p>`);
 $('#cancelProjectDeletion').onclick=()=>$('#modal').close();$('#cancelProjectDeletion').focus();
 $('#confirmProjectDeletion').onclick=e=>task(e.target,()=>deleteSavedProject(ident));
}
async function deleteSavedProject(ident){
 if(generating||designBusy)throw Error('Wait for the current project operation to finish.');
 const controls=['#saveProject','#deleteProject','#reviewProject','#projectSelect','#newProject','#importProject'].map(s=>$(s)),states=controls.map(el=>el.disabled);
 controls.forEach(el=>el.disabled=true);
 try{
  const result=await api('/api/project/delete',{id:ident,confirm:true});
  project=null;dirty=false;report=proposal=previousDraft=null;areaIndex=roomIndex=npcIndex=questIndex=templateIndex=0;page='brief';
  app.projects=result.projects;projectList();$('#modal').close();render();
  const next=app.projects.find(p=>p.schema_version===2);if(next)await load(next.id);
  projectList();notify('Project deleted from this computer.');
 }catch(error){
  const status=$('#deleteProjectStatus');if(status)status.textContent=error.message;
  throw error;
 }finally{
  controls.forEach((el,i)=>el.disabled=states[i]);
  if(!project){['#saveProject','#deleteProject','#reviewProject'].forEach(s=>$(s).disabled=true);$('#projectSelect').disabled=!app.projects.some(p=>p.schema_version===2);}
 }
}
function assistant(defaultScope){return `<aside class="author-aside"><div class="card accent"><div class="card-head"><h3>${project.design_mode==='area'?'AI · Area design':'AI DM · Adventure design'}</h3><span class="badge">Authoring</span></div><p class="muted">${project.design_mode==='area'?'Design rooms and their contents independently of any adventure.':'Turn your storyline and design notes into playable content.'} Every generated proposal is editable.</p><label class="field"><span>What should the AI create?</span><select id="aiScope">${[['adventure','Complete adventure'],['story','Story and ending prose'],['areas','Areas, rooms and connections'],['cast','Characters and dialogue'],['companions','Companions and starting templates'],['behaviors','Patrols and NPC social behavior'],['encounters','Encounters, items and furnishings'],['quests','Quests and supporting cast'],['populate','Populate the selected area']].filter(([v])=>project.design_mode!=='area'||!['adventure','story','quests'].includes(v)).map(([v,t])=>`<option value="${v}" ${v===defaultScope?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Your direction</span><textarea id="aiDirection" placeholder="Use my storyline. Give each room a purpose, add characters with different motives, and create quests that lead to a complete ending."></textarea></label><button data-action="generate" class="primary" ${generating?'disabled':''}>Generate proposal</button><p class="hint">The AI uses your story, room plans, character notes and encounter briefs. It creates native game content for export.</p>${previousDraft?'<button data-action="undoAI" class="quiet">Undo last applied proposal</button>':''}</div><div class="note">Generation happens while authoring. The exported adventure includes its story, conversations and quest logic and can be played without this editor.</div></aside>`;}
function brief(){return `<div class="hero"><span class="badge">Build a complete adventure</span><h2 class="after-card">From your storyline to their next game.</h2><p>Describe the world, define its spaces and characters, then let the AI DM build quests and encounters around them. Review the result and export a module players can run locally and share.</p><div class="flow"><span>Storyline</span><b>→</b><span>Areas & rooms</span><b>→</b><span>Characters & quests</span><b>→</b><span>Playable .mod</span></div></div><div class="author-grid"><div><div class="card">${field('Adventure title','title')}${field('Public premise','summary','textarea')}${field('Storyline · events, characters, twists, desired resolution','story','textarea')}${field('Tone and style','tone','textarea')}<div class="row three">${field('Minimum party level','level_min','number')}${field('Maximum party level','level_max','number')}${field('Intended party size','party_size','number')}</div></div><div class="card"><h3>The player’s journey</h3>${field('Opening narration','opening','textarea')}${field('Ending narration','ending','textarea')}${field('Starting room','start_room','select',roomOptions())}<p class="hint">Quest choices can have their own outcome text and different final objectives. The ending narration appears when every main quest is complete.</p></div></div>${assistant('adventure')}</div>`;}
function worldMap(a){const layout=report?.layouts?.[a.id];const w=a.width,h=a.height;const roomMap=Object.fromEntries(a.rooms.map(r=>[r.id,r]));
 const port=(r,s)=>({north:[r.x+r.width/2,r.y+r.height-.2],south:[r.x+r.width/2,r.y+.2],east:[r.x+r.width-.2,r.y+r.height/2],west:[r.x+.2,r.y+r.height/2]}[s]);
 let exits='';project.connections.forEach(c=>{for(const [rid,side,dest] of [[c.from_room,c.from_side,c.to_room],[c.to_room,c.to_side,c.from_room]]){const r=roomMap[rid];if(!r)continue;const doorway=(layout?.doorways||[]).find(d=>d.room===rid&&d.side===side);if(doorway){exits+=`<rect x="${doorway.x/10-.14}" y="${h-doorway.y/10-.14}" width=".28" height=".28" fill="#edc078"><title>Walk-through doorway: ${E(r.name)} to ${E(dest)}</title></rect>`;continue;}const opening=(layout?.openings||[]).find(d=>d.room===rid&&d.side===side);if(opening){exits+=`<rect x="${opening.x/10-.14}" y="${h-opening.y/10-.14}" width=".28" height=".28" fill="#53e2e2"><title>Open passage: ${E(r.name)} to ${E(dest)}</title></rect>`;continue;}const [x,y]=port(r,side);exits+=`<circle class="exit" cx="${x}" cy="${h-y}" r=".22"><title>${E(c.name)}: ${side} to ${E(dest)}</title></circle>`;}});
 return `<svg class="worldmap" viewBox="${mapViewBox(a)}" role="group" tabindex="0" aria-label="Room plan for ${E(a.name)}" aria-describedby="mapViewHint"><defs><pattern id="planGrid" width="1" height="1" patternUnits="userSpaceOnUse"><path class="mapgrid" d="M 1 0 L 0 0 0 1" fill="none"/></pattern></defs>${mapBackground(a)}<rect width="${w}" height="${h}" fill="url(#planGrid)"/>${a.geometry?(layout?.rectangles||[]).map(([x1,y1,x2,y2])=>`<rect class="corridor" x="${x1/10}" y="${h-y2/10}" width="${(x2-x1)/10}" height="${(y2-y1)/10}"/>`).join(''):''}${(a.geometry?[]:(layout?.corridors||[])).flatMap(c=>c.cells.map(([x,y])=>`<rect class="corridor" x="${x}" y="${h-y-1}" width="1" height="1"/>`)).join('')}${a.rooms.map((r,i)=>`<g><rect data-room-map="${i}" class="room ${i===roomIndex?'selected-room':''}" x="${r.x}" y="${h-r.y-r.height}" width="${r.width}" height="${r.height}" rx="${a.type==='cave'?.3:.08}"/><text class="room-label" textLength="${Math.min(r.width-.3,Math.min(r.name.length,26)*.23)}" lengthAdjust="spacingAndGlyphs" x="${r.x+r.width/2}" y="${h-r.y-r.height/2-.1}">${E(r.name.slice(0,26))}</text><text class="room-detail" x="${r.x+r.width/2}" y="${h-r.y-r.height/2+.55}">${roomMetres(r)[0]} × ${roomMetres(r)[1]} m clear</text></g>`).join('')}${exits}<g class="map-tools">${mapExtras(a)}</g><g class="map-fixtures">${objectMarkers(a)}</g></svg>`;
}
let assetLibrary={packs:[],assets:[]};
function designReferences(a,ap){return `<div class="card"><h3>Floor plans and visual references</h3>${a.design_plan?'<button data-action="reviewSavedChecklist">Review saved objects and scale</button>':''}<p class="hint">Upload an image, add optional notes, and generate a fully populated area. The AI infers room count, size, connections, furnishings and characters. No storyline is required in an area workspace. Generation first shows an AI-generated object checklist and scale estimates for review.</p><input id="floorplanUpload" type="file" accept="image/png,image/jpeg,image/webp" multiple><div class="actions"><select id="generationFloorplan" aria-label="Floor plan to generate from" ${(a.references||[]).length?'':'disabled'}>${(a.references||[]).length?(a.references||[]).map((r,i)=>`<option value="${i}">${E(r.name)}</option>`).join(''):'<option>Upload a floor plan first</option>'}</select><button data-action="generateSelectedFloorplan" class="primary" ${generating||!(a.references||[]).length?'disabled':''}>Generate from floor plan</button><button data-action="openAurora" ${generating||!a.rooms.length?'disabled':''}>Open in Aurora</button></div><p class="hint">After generating, review and apply the proposal, then open the current area in Aurora. This builds an editable module copy and does not call the AI.</p><p class="hint">PNG, JPEG or WebP, up to 2 MB each and three images per area. The selected image is sent to your configured AI provider when you generate.</p>${(a.references||[]).map((r,i)=>`<div class="reference-card"><img src="${E(r.data_url)}" alt="${E(r.name)}" class="floorplan-preview"><strong>${E(r.name)}</strong>${field('Description and optional scale notes',ap+'.references.'+i+'.notes','textarea')}<button data-action="remove_reference_${i}" class="quiet">Remove reference</button></div>`).join('')}<details><summary>Advanced layout review</summary><button data-action="interpretFloorplan" ${generating||!(a.references||[]).length?'disabled':''}>Review interpretation only</button></details></div>`;}

function customContentPanel(){const packs=project.custom_packs||[],selected=new Set(packs.map(p=>p.pack));return `<details class="card asset-catalog" ${foldAttributes('asset-catalog')}><summary><strong>Visual asset catalog</strong><span class="hint">${assetLibrary.assets.length.toLocaleString()} assets · expand to browse and add</span></summary><p>${assetLibrary.builtin_count||0} installed placeables plus ${assetLibrary.assets.length-(assetLibrary.builtin_count||0)} imported entries. Browse actual model shapes; use Aurora to verify textures and effects.</p><details class="area-foldout" ${foldAttributes('content-sources')}><summary>Content folders and HAK packs</summary><p class="hint">Point Studio to a .hak/.erf or an extracted folder of NWN resources. All scanned placeable objects become searchable by the authoring AI; you do not need to add them to a room first. Required packs accompany the shared adventure. Only share content you have permission to redistribute.</p><div class="row"><input id="contentPath" value="${E(app.settings.content_root||'')}" placeholder="Full path to a HAK/ERF or extracted content folder"><button data-action="scanContent">Scan content location</button></div><p class="hint">A folder scan includes HAK/ERF files and supported loose models, textures, placeables and 2DAs. Select supporting packs below when an asset requires them. Pack order is shown; incompatible placeables tables are rejected at build time.</p>${assetLibrary.packs.map(p=>`<label class="field"><span><input type="checkbox" data-content-pack="${E(p.pack)}" ${selected.has(p.pack)?'checked':''}> ${E(p.label)} · ${p.resources} resources${p.tilesets.length?' · tilesets discovered: '+E(p.tilesets.join(', '))+' (Aurora use; automatic tile generation not yet supported)':''}</span></label>`).join('')}</details><label class="field"><span>Find a placeable or furnishing</span><input id="assetSearch" placeholder="table, bed, statue…"></label><div id="visualAssetGrid"></div><div class="actions"><button type="button" id="assetPrev">Previous page</button><span id="assetPageLabel"></span><button type="button" id="assetNext">Next page</button></div><label class="field"><span>Selected asset</span><select id="customAsset">${assetLibrary.assets.slice(0,200).map(a=>`<option value="${E(a.id)}">${E(a.name)} · ${E(a.pack)}</option>`).join('')}</select></label><button data-action="addCustomAsset" ${assetLibrary.assets.length?'':'disabled'}>Add selected asset to current room</button><p class="hint">The visual catalog pages through every matching asset; AI search covers the full catalog. Generation first searches for useful objects, then uses them only when appropriate. Only chosen assets and their HAKs are added to the generated project; explicitly selected supporting packs are retained. Placement uses a conservative footprint; inspect unusually large props in Aurora.</p></details>`;}
function placedAssetsPanel(a){
 const rooms=new Map(a.rooms.map(r=>[r.id,r.name])),placed=['furnishings','custom_placements'].flatMap(collection=>(project[collection]||[]).map((f,i)=>({f,i,collection}))).filter(({f})=>rooms.has(f.room));
 return `<details class="card area-foldout" ${foldAttributes('placed-furnishings')}><summary>Placed furnishings · ${placed.length}</summary><p class="hint">All basic furnishings and catalog placements in this area are listed here, including automatically positioned items. Expand an item to edit or remove it.</p><button data-action="addFurniture">＋ Basic furnishing to current room</button>${placed.map(({f,i,collection})=>{
  const p=collection+'.'+i,basic=collection==='furnishings',positioned=(project.object_positions||[]).some(pos=>pos.id===f.id);
  return `<details class="area-foldout" ${foldAttributes('placement:'+project.id+':'+f.id)}><summary>${E(f.name)} <span class="hint">· ${E(rooms.get(f.room))} · ${basic?'Basic furnishing':'Catalog asset'}</span></summary>${field('Furnishing name',p+'.name')}${field('Room',p+'.room','select',roomOptions())}${basic?field('Object',p+'.kind','select',app.authoring_catalog.furnishings):''}${field('Preferred placement',p+'.placement','select',['north','east','south','west','center'])}<p class="hint">${positioned?'This item has a fixed position. Use Precise object placement below or the visual area editor to move it; preferred placement applies only to automatic placement.':'Automatically positioned during the build, with clearance for doors and other objects.'}</p>${field('Design notes',p+'.description','textarea')}<button data-remove="${collection}:${i}" class="danger">Remove furnishing</button></details>`;
 }).join('')||'<p class="muted">No furnishings in this area yet. Add a basic furnishing here or choose an asset from the catalog.</p>'}</details>`;
}

const AREA_SECTIONS={
 overview:['Area settings','Set the area type, size and design brief.'],
 floorplans:['Floor plans','Upload references and review the AI-generated room plan.'],
 materials:['Materials & lighting','Choose surface finishes and the atmosphere for this area.'],
 layout:['Layout & connections','Edit rooms, boundaries, stairs and connecting doorways.'],
 assets:['Assets & placement','Browse furnishings and adjust their placement.']
};
let areaSection='overview';
const openFoldouts=new Set();
function foldAttributes(key){return `data-ui-fold="${E(key)}" ${openFoldouts.has(key)?'open':''}`;}
function syncAreaSections(){
 const nav=$('#areaNavigation');if(!nav)return;nav.hidden=page!=='world';
 document.querySelector('nav [data-page="world"]').setAttribute('aria-expanded',String(page==='world'));
 document.querySelectorAll('[data-area-section]').forEach(b=>{const active=page==='world'&&b.dataset.areaSection===areaSection;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 document.querySelectorAll('[data-area-panel]').forEach(el=>el.hidden=el.dataset.areaPanel!==areaSection);
 if($('#areaSectionTitle'))$('#areaSectionTitle').textContent=AREA_SECTIONS[areaSection][0];
 if($('#areaSectionDescription'))$('#areaSectionDescription').textContent=AREA_SECTIONS[areaSection][1];
}
function showAreaSection(section){
 if(!AREA_SECTIONS[section])return;
 if(generating||designBusy){notify('Wait for the current design operation to finish.');return;}
 const samePage=page==='world';areaSection=section;page='world';
 // Keep existing form nodes: switching sections must retain unsaved input and selections.
 if(samePage)syncAreaSections();else render();
 scrollWorkspaceTop();
}
function bindAreaSections(){
 syncAreaSections();
 document.querySelectorAll('[data-area-section]').forEach(b=>b.onclick=()=>showAreaSection(b.dataset.areaSection));
 document.querySelectorAll('[data-ui-fold]').forEach(el=>el.ontoggle=()=>{if(el.open)openFoldouts.add(el.dataset.uiFold);else openFoldouts.delete(el.dataset.uiFold);});
}

function world(){if(!project.areas.length)return `<div class="card"><h2>Design the first area.</h2><button data-action="addArea" class="primary">Add area</button></div>`;areaIndex=Math.min(areaIndex,project.areas.length-1);roomIndex=Math.min(roomIndex,Math.max(0,area().rooms.length-1));const a=area(),ap='areas.'+areaIndex,r=selectedRoom(),rp=ap+'.rooms.'+roomIndex;
 const panel=(key,body)=>`<section id="area-panel-${key}" data-area-panel="${key}" aria-label="${E(AREA_SECTIONS[key][0])}" ${areaSection===key?'':'hidden'}>${body}</section>`;
 const overview=`${workshopPanel()}<div class="card"><div class="row">${field('Area name',ap+'.name')}${field('Area type',ap+'.type','select',Object.entries(app.authoring_catalog.area_types))}</div>${field('How should this area look and feel? What belongs here?',ap+'.description','textarea')}<div class="row three">${field('Width · tiles (10 m each)',ap+'.width','number')}${field('Height · tiles (10 m each)',ap+'.height','number')}${field('Requested room count',ap+'.room_count','number')}</div>${!a.look||a.look.lighting==='legacy'?field('Basic lighting',ap+'.lighting','select',['warm','cold','dark','daylight']):''}<div class="actions"><button data-action="generateArea" class="primary" ${generating?'disabled':''}>Generate area with AI</button><button data-action="arrange">Generate room layout</button><button data-action="connectRooms">Connect these rooms</button></div><p class="hint">Generate area with AI uses this area’s settings, floor plans and your story to propose connected rooms, characters, encounters and furnishings. Review and apply the proposal before building. Basic room layout generation respects the area size and requested room count. Connecting rooms creates editable corridors. Use exit connections between different areas.</p></div><p class="hint">${project.design_mode==='area'?'Open in Aurora builds a standalone preview of this area.':'Open in Aurora builds this adventure and opens a separate editable module copy.'} Select this area in Aurora’s Areas tree. Apply your AI proposal first; ${project.design_mode==='area'?'only area layout and content checks are required.':'the adventure must pass build checks.'} Aurora edits are kept in that copy and are not imported into Studio.</p><details><summary>Area identity and removal</summary>${field('Area resource ID',ap+'.id')}<button data-action="deleteArea" class="danger">Remove area from draft</button></details>`;
 const layout=`${r?`<div class="card"><div class="card-head"><h3>Room design</h3><button class="quiet danger" data-action="deleteRoom">Remove room</button></div>${field('Room name',rp+'.name')}${field('Visual description and contents',rp+'.description','textarea')}${field('Purpose in the adventure',rp+'.purpose')}<div class="row">${field('X · tiles from west',rp+'.x','number')}${field('Y · tiles from south',rp+'.y','number')}</div><div class="row">${field('Room width · tiles',rp+'.width','number')}${field('Room height · tiles',rp+'.height','number')}</div><p class="hint">Leave at least two empty tiles between rooms and a one-tile border around the area. Add furnishings in Encounters & items or ask AI to populate this area.</p><details><summary>Resource identity</summary>${field('Room ID',rp+'.id')}<p class="hint">Connections and quest objectives reference this ID.</p></details></div>`:''}${designPanel(a)}<div class="section-head after-card"><div><h3>Room and area connections</h3><p class="hint">Every connection specifies an exit side and a destination.</p></div><button data-action="addConnection">＋ Connection</button></div><div class="connections">${project.connections.map((c,i)=>{if(!a.rooms.some(r=>r.id===c.from_room||r.id===c.to_room))return '';let p='connections.'+i;return `<div class="connection-card"><div class="card-head"><strong>${E(c.name)}</strong><button data-remove="connections:${i}" class="quiet danger">Remove</button></div>${field('Passage name',p+'.name')}<div class="row">${field('From room',p+'.from_room','select',roomOptions())}${field('Exit side',p+'.from_side','select',['north','east','south','west'])}</div><div class="row">${field('To room / area',p+'.to_room','select',roomOptions())}${field('Arrival side',p+'.to_side','select',['north','east','south','west'])}</div><div class="row">${field('Connection type',p+'.kind','select',[['corridor','Physical corridor · same area'],['exit','Area / room transition']])}${field('Open after quest',p+'.requires_quest','select',questOptions())}</div>${field('Travel both ways',p+'.two_way','checkbox')}${doorwayFields(c,i,a)}</div>`;}).join('')||'<div class="empty">Add a connection to another room or area.</div>'}</div>`;
 const assets=`${customContentPanel()}${placedAssetsPanel(a)}<details class="card area-foldout" ${foldAttributes('precise-placement')}><summary>Precise object placement</summary>${positionPanel(a)}</details>`;
 return `<div class="section-head"><div><div class="eyebrow">AREAS & ROOMS</div><h2 id="areaSectionTitle">${E(AREA_SECTIONS[areaSection][0])}</h2><p class="muted" id="areaSectionDescription">${E(AREA_SECTIONS[areaSection][1])}</p></div><button data-action="addArea">＋ Add area</button></div><div class="tabs" aria-label="Areas">${project.areas.map((a,i)=>`<button data-area="${i}" class="${i===areaIndex?'active':''}">${E(a.name)}</button>`).join('')}</div><div class="area-room-context"><strong>Room</strong><div class="room-picker">${a.rooms.map((r,i)=>`<button data-room="${i}" class="${i===roomIndex?'active':''}">${E(r.name)}</button>`).join('')}<button data-action="addRoom">＋ Room</button></div></div><div class="card area-build-tools"><div class="actions"><button data-action="updateArea" class="primary">Update generated area</button><button data-action="openAurora">Open in Aurora</button><button data-action="testArea">Install area for testing</button><button data-action="preview">Check connections</button></div><div id="designStatus" role="status"></div><div id="auroraResult" role="status"></div></div><div class="author-grid"><div>${panel('overview',overview)}${panel('floorplans',designReferences(a,ap))}${panel('materials',presetPanel(a))}${panel('layout',layout)}${panel('assets',assets)}</div>${assistant('areas')}</div>`;
}
function encounters(){return `<div class="section-head"><div><h2>Fill the adventure with encounters.</h2><p class="muted">Describe combat, ambushes, puzzles, treasure and story moments. Generate them with the AI DM or author each detail.</p></div><button data-action="addEncounter">＋ Encounter</button></div><div class="author-grid"><div>${project.encounters.map((e,i)=>{const p='encounters.'+i;return `<div class="card"><div class="card-head"><span class="badge">${E(e.kind)}</span><button class="quiet danger" data-remove="encounters:${i}">Remove</button></div>${field('Encounter name',p+'.name')}<div class="row">${field('Kind',p+'.kind','select',['combat','ambush','puzzle','treasure','story'])}${field('Room',p+'.room','select',roomOptions())}</div>${field('Describe the encounter you want',p+'.description','textarea')}${field('Available after quest',p+'.after_quest','select',questOptions())}${['combat','ambush'].includes(e.kind)?`<div class="row">${field('Creature',p+'.creature','select',app.authoring_catalog.creatures)}${field('Base number',p+'.count','number')}</div><div class="row">${field('Maximum number',p+'.maximum','number')}${field('Scale count with party size and level',p+'.scale','checkbox')}</div><p class="hint">Combat creatures are placed in the module. Ambushes activate when the party enters the room. Scaling runs inside NWN and needs no AI service.</p>`:`${field('Interaction / puzzle text',p+'.prompt','textarea')}${e.kind==='puzzle'?`<label class="field"><span>Puzzle options · one per line</span><textarea data-lines="${p}.options">${E(e.options.join('\n'))}</textarea></label>${field('Correct option · first option is 0',p+'.answer','number')}${field('Incorrect answer response',p+'.failure','textarea')}`:''}${field('Success / resolution text',p+'.success','textarea')}<div class="row">${field('Gold reward',p+'.gold','number')}${field('XP reward',p+'.xp','number')}</div>`}<details><summary>Resource identity</summary>${field('Encounter ID',p+'.id')}</details></div>`;}).join('')||'<div class="empty">No encounters yet. Add a brief or ask the AI DM to generate them.</div>'}<div class="section-head after-card"><h3>Items and quest objects</h3><button data-action="addItem">＋ Item</button></div>${project.items.map((item,i)=>{let p='items.'+i;return `<div class="card"><div class="card-head"><h3>${E(item.name)}</h3><button data-remove="items:${i}" class="quiet danger">Remove</button></div>${field('Name',p+'.name')}${field('Description',p+'.description','textarea')}<div class="row">${field('Kind',p+'.kind','select',[['quest_token','Quest object'],['healing_potion','Healing potion']])}${field('Quantity',p+'.quantity','number')}</div>${field('Room',p+'.room','select',roomOptions())}${field('Container',p+'.container','select',[['','Own cache'],...project.encounters.filter(e=>e.kind==='treasure').map(e=>[e.id,e.name])])}<details><summary>Resource identity</summary>${field('Item ID',p+'.id')}</details></div>`;}).join('')}<div class="card"><h3>Curated room design</h3><p>Preview a compact furniture arrangement. Replaces furnishings in the selected room only; story objects stay in place.</p><label>Room <select id="designRoom">${roomOptions().map(([id,name])=>`<option value="${E(id)}">${E(name)}</option>`).join('')}</select></label><label>Design <select id="designStyle"><option value="reading_room">Reading room</option><option value="bedchamber">Bedchamber</option><option value="merchant">Merchant</option><option value="dining">Dining room</option><option value="abandoned">Abandoned room</option><option value="camp">Supply camp</option></select></label><button data-action="roomDesign">Preview room design</button></div><div class="section-head after-card"><h3>Furniture and scenery</h3><button data-action="addFurniture">＋ Furnishing</button></div>${project.furnishings.length?`<div class="entity-grid">${project.furnishings.map((f,i)=>{let p='furnishings.'+i;return `<div class="card compact-fields"><div class="card-head"><strong>${E(f.name)}</strong><button data-remove="furnishings:${i}" class="quiet danger">×</button></div>${field('Name',p+'.name')}${field('Room',p+'.room','select',roomOptions())}${field('Object',p+'.kind','select',app.authoring_catalog.furnishings)}${field('Preferred placement',p+'.placement','select',['north','east','south','west','center'])}${field('Description',p+'.description','textarea')}</div>`;}).join('')}</div>`:'<p class="muted">Ask AI to populate rooms with appropriate furnishings or add them here.</p>'}</div>${assistant('encounters')}</div>`;}
function merchantEditor(n,p){const m=n.merchant;const stockPath=p+'.merchant.stock';const goods=app.authoring_catalog.merchandise;return `<div class="card"><h3>Merchant shop</h3>${field('Enable a finite-stock shop',p+'.merchant.enabled','checkbox')}<p class="hint">Players can browse from the NPC menu or ask through AI chat. Players confirm trades in the in-game shop window.</p>${m.enabled?`${field('Shop interface',p+'.merchant.interface','select',[['native','Native visual store - buy and sell'],['list','Text list - fixed prices, buy only']])}<p class="hint">${m.interface==='native'?'Native stores show item icons and use NWN pricing, including Appraise. The displayed price is authoritative. Merchants buy eligible items for up to 5,000 gold each; no automatic restocking.':'List shops use the exact authored prices below and sell to players only.'}</p>${m.stock.map((sku,i)=>{const path=stockPath+'.'+i;return `<div class="branch"><div class="card-head"><strong>${E(goods[sku.item].name)}</strong><button data-remove="${stockPath}:${i}" class="quiet danger">Remove stock</button></div>${field('Stock item',path+'.item','select',Object.entries(goods).map(([k,v])=>[k,v.name]))}<div class="row">${field('Initial quantity',path+'.quantity','number')}${m.interface==='list'?field('Unit price · gold',path+'.price','number'):''}</div></div>`;}).join('')}<button data-action="addStock" ${m.stock.length>=8?'disabled':''}>＋ Stock item</button><p class="hint">Up to 8 goods and 80 total items. Stock is finite and saved with the game. Native stores retain eligible items sold by players; neither interface automatically restocks.</p>${field('Allow haggling',p+'.merchant.haggle_enabled','checkbox')}${m.haggle_enabled?`<div class="row">${field('Success chance · percent',p+'.merchant.haggle_chance','number')}${field('Discount · percent (0–10)',p+'.merchant.discount_percent','number')}</div>${field('Offer duration · active game seconds',p+'.merchant.offer_seconds','number')}<p class="hint">The game rolls once per offer period. Repeated requests reuse that result; discounts do not stack. In native stores, the price applies for that open shopping window; reopening checks the offer expiry.</p>`:''}`:''}</div>`;}
function recruitEditor(n,p){const c=n.companion;return `<div class="card"><h3>Party companion</h3>${field('Allow this character to be recruited',p+'.companion.recruitable','checkbox')}${c.recruitable?`${field('Protect this essential story companion',p+'.companion.essential','checkbox')}${field('Recruit after quest',p+'.companion.requires_quest','select',questOptions('Available from the beginning'))}${field('Communication',p+'.companion.communication','select',[['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions'],['auto','Automatic from creature type']])}${field('Allow follow, stand-ground and guard orders',p+'.companion.movement','checkbox')}${field('Allow native inventory exchanges',p+'.companion.inventory','checkbox')}${field('Allow inspecting accessible containers',p+'.companion.inspect_containers','checkbox')}${field('Allow owner-directed NPC visits',p+'.companion.social_visits','checkbox')}<p class="hint">Enable companion support in Companions. Recruits use the stock guard combat template and equipment; refine classes and gear in Aurora. Native combat and party controls remain active. A merchant cannot also be a recruit.</p><button data-action="companionSettings">Open companion settings</button>`:''}</div>`;}
function behaviors(){npcIndex=Math.min(npcIndex,Math.max(0,project.npcs.length-1));const n=project.npcs[npcIndex],b=n?.behavior,p='npcs.'+npcIndex+'.behavior';return `<div class="section-head"><div><h2>A world that moves and talks.</h2><p class="muted">Set native patrols and optional public conversations between authored characters.</p></div></div><div class="author-grid"><div><div class="card"><h3>Module behavior switches</h3><button data-action="applyAIDefaults">Apply conversation &amp; storage defaults to this project</button><p class="hint">New characters start with conversations, unrestricted social partners and companion errands enabled. Apply these defaults to an older project, then rebuild it. Individual controls remain editable below.</p>${field('Enable native patrols','ambient.patrols','checkbox')}${field('Enable NPC-to-NPC AI conversations','ambient.social','checkbox')}${field('Minimum seconds between exchange attempts','ambient.social_interval','number')}${field('Exchange attempts per active game hour','ambient.social_budget','number')}<p class="hint">Patrols work offline. Social conversations need live AI enabled at export and the local AI Player running. Each exchange uses two short AI requests; failed or interrupted attempts consume budget too.</p></div>${n?`<div class="card"><h3>Character behavior</h3><label class="field"><span>Behavior character</span><select id="npcSelect" aria-label="Behavior character">${project.npcs.map((o,i)=>`<option value="${i}" ${i===npcIndex?'selected':''}>${E(o.name)}</option>`).join('')}</select></label>${field('Enable patrol for this character',p+'.patrol_enabled','checkbox')}${field('Route pattern',p+'.mode','select',[['loop','Loop'],['pingpong','Back and forth']])}${field('Wait at each stop · seconds',p+'.wait_seconds','number')}${field('Run between stops',p+'.run','checkbox')}<h4>Ordered patrol stops</h4>${b.route.map((r,i)=>`<div class="card">${field('Stop '+(i+1),p+'.route.'+i,'select',roomOptions())}<div class="actions"><button data-route-up="${i}" ${i===0?'disabled':''}>Move stop up</button><button data-remove="${p}.route:${i}" class="quiet">Remove stop</button></div></div>`).join('')}<button data-action="addPatrolStop">＋ Patrol stop</button><p class="hint">Use at least two reachable rooms in the character’s starting area, connected by ordinary corridors. Exits do not teleport patrols. Player conversations, combat, possession and recruitment take priority; blocked paths wait before retrying.</p></div><div class="card"><h3>Public NPC conversations</h3>${field('Allow this character to chat with NPCs',p+'.social_enabled','checkbox')}${field('Accept owner-directed companion visits',p+'.accept_visits','checkbox')}<label class="field"><span>Allowed partners · empty allows all opted-in characters</span><select multiple data-multi="${p}.partners">${project.npcs.filter(o=>o.id!==n.id).map(o=>`<option value="${E(o.id)}" ${b.partners.includes(o.id)?'selected':''}>${E(o.name)}</option>`).join('')}</select></label>${field('Public conversation topic',p+'.topic','textarea')}${field('Character cooldown · active seconds',p+'.cooldown','number')}${field('Social communication',p+'.communication','select',[['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions']])}<p class="hint">Both characters must enable social chat and allow each other. They need live AI enabled on their character profiles. Only unowned, idle, nearby, mutually visible actors converse. Each speaker receives their own public knowledge and the pair’s public speech history. Put hidden facts in Secret knowledge, never unconditional knowledge or the public topic.</p></div>`:'<div class="card"><p>Add characters before configuring individual behavior.</p></div>'}<div class="note">Social speech cannot move items, spend gold, change quests or order another actor. Native combat and creature heartbeat scripts remain active. Companions stop ambient patrols/social chat while recruited.</div></div>${assistant('behaviors')}</div>`;}
function companions(){const cfg=project.companions;templateIndex=Math.min(templateIndex,Math.max(0,cfg.templates.length-1));const t=cfg.templates[templateIndex],p='companions.templates.'+templateIndex;const types=[[-1,'Fallback / exact blueprints only'],[0,'Bat'],[1,'Cat / panther'],[2,'Hell hound'],[3,'Imp'],[4,'Fire mephit'],[5,'Ice mephit'],[6,'Pixie'],[7,'Raven'],[8,'Faerie dragon'],[9,'Pseudodragon'],[10,'Eyeball / beholder kin'],[255,'Other native familiar type']];return `<div class="section-head"><div><h2>Companions with their own character.</h2><p class="muted">Create recruitable party members and personalities for the game's actual familiars and summons.</p></div><button data-action="addCompanionTemplate">＋ Custom template</button></div><div class="author-grid"><div><div class="card"><h3>Module companion rules</h3><button data-action="applyAIDefaults">Apply conversation &amp; storage defaults to this project</button>${field('Enable companion support','companions.enabled','checkbox')}${field('Maximum recruitable companions','companions.party_limit','number')}${field('Enable familiar companions','companions.familiars','checkbox')}${field('Enable summoned companions','companions.summons','checkbox')}<p class="hint">Set recruitment and its quest requirements on individual characters. Familiar and summon profiles attach to existing game creatures; they do not grant spells or summon replacements. Players can restrict these permissions in game.</p></div><div class="card"><h3>Starting personalities</h3><p class="hint">Specific blueprint matches take priority, then familiar type, then one fallback per kind. Edit an existing type to change its starting personality. Add a custom template for a different blueprint.</p>${t?`<div class="select-row"><select id="templateSelect" aria-label="Companion template">${cfg.templates.map((o,i)=>`<option value="${i}" ${i===templateIndex?'selected':''}>${E(o.name)} · ${E(o.kind)}</option>`).join('')}</select><button data-remove="companions.templates:${templateIndex}" class="quiet danger">Remove template</button></div>${field('Template name',p+'.name')}${field('Companion kind',p+'.kind','select',[['familiar','Familiar'],['summon','Summon']])}${t.kind==='familiar'?field('Native familiar type',p+'.familiar_type','select',types):''}<label class="field"><span>Exact creature blueprints · one per line</span><textarea data-lines="${p}.blueprints">${E(t.blueprints.join('\n'))}</textarea></label>${field('Role and relationship',p+'.role')}${field('Personality and preferences',p+'.personality','textarea')}${field('Personal knowledge',p+'.knowledge','textarea')}${field('Boundaries and game guidance',p+'.game_notes','textarea')}${field('Communication style',p+'.communication','select',[['auto','Automatic · animals nonverbal'],['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions']])}${field('Allow live AI conversation',p+'.ai_enabled','checkbox')}${field('Allow AI movement orders',p+'.movement','checkbox')}${field('Allow recoverable satchel inventory',p+'.inventory','checkbox')}${field('Allow inspecting accessible containers',p+'.inspect_containers','checkbox')}${field('Allow owner-directed NPC visits',p+'.social_visits','checkbox')}<details><summary>Template identity</summary>${field('Template ID',p+'.id')}</details>`:'<p class="muted">No familiar or summon templates. Add a template to enable a selected creature.</p>'}</div><div class="note">In game, use !companions for recruitment, follow/stay/guard, conversation preferences and inventory. Familiar history survives resummoning; each summon has a separate identity. Satchels stay in the owner’s inventory for recovery after dismissal. Native game menus, combat and summoning remain active.</div></div>${assistant('companions')}</div>`;}
function cast(){npcIndex=Math.min(npcIndex,Math.max(0,project.npcs.length-1));const n=project.npcs[npcIndex],p='npcs.'+npcIndex;return `<div class="section-head"><div><h2>Characters who belong in the story.</h2><p class="muted">Define their voice, knowledge, secrets and purpose. The AI DM can create the supporting cast from your storyline.</p></div><button data-action="addNPC">＋ Character</button></div><div class="author-grid"><div>${n?`<div class="select-row"><select id="npcSelect" aria-label="Character">${project.npcs.map((n,i)=>`<option value="${i}" ${i===npcIndex?'selected':''}>${E(n.name)}</option>`).join('')}</select><button class="quiet danger" data-action="deleteNPC">Remove</button></div><div class="card"><div class="row">${field('Name',p+'.name')}${field('Role in the story',p+'.role')}</div><div class="row">${field('Room',p+'.room','select',roomOptions())}${field('Native appearance',p+'.appearance','select',app.authoring_catalog.appearances)}</div>${field('Personality and speaking style',p+'.personality','textarea')}${field('Knowledge · facts this character can share',p+'.knowledge','textarea')}${field('Motivation and relationship to the story',p+'.motivation','textarea')}${field('Game-related details · hints, constraints, promises to avoid',p+'.game_notes','textarea')}${field('Secret knowledge',p+'.secret','textarea')}${field('Reveal secret after quest',p+'.reveal_after','select',questOptions('Known from the beginning'))}</div><div class="card"><h3>Authored conversations</h3><p class="hint">These lines are compiled into the module and work for every player without an API key.</p>${field('Opening line',p+'.greeting','textarea')}${n.dialogue.map((d,i)=>`<div class="branch">${field('Player topic',p+'.dialogue.'+i+'.topic')}${field('NPC response',p+'.dialogue.'+i+'.text','textarea')}${field('Unlock after quest',p+'.dialogue.'+i+'.after_quest','select',questOptions())}<button data-remove="npcs.${npcIndex}.dialogue:${i}" class="quiet danger">Remove topic</button></div>`).join('')}<button data-action="addTopic">＋ Dialogue topic</button></div>${merchantEditor(n,p)}${recruitEditor(n,p)}<div class="card"><h3>AI conversation</h3>${field('Allow AI conversation for this character',p+'.ai_enabled','checkbox')}${field('Chat alias',p+'.alias')}<p class="character-note">Profiles guide AI-generated dialogue during authoring. Live freeform conversation can also be included at export, with an optional local player companion. The main story always has authored dialogue.</p><details><summary>Resource identity</summary>${field('NPC ID',p+'.id')}</details></div>`:'<div class="empty">Add your key characters or let the AI DM create a cast for your story.</div>'}</div>${assistant('cast')}</div>`;}
function stepTargets(s){return s.kind==='talk'||s.kind==='choice'?project.npcs.map(n=>[n.id,n.name]):s.kind==='visit'?roomOptions():s.kind==='retrieve'?project.items.map(i=>[i.id,i.name]):project.encounters.filter(e=>s.kind==='defeat'?['combat','ambush'].includes(e.kind):!['combat','ambush'].includes(e.kind)).map(e=>[e.id,e.name]);}
function quests(){return `<div class="section-head"><div><h2>Story & mission editor</h2><p class="muted">Shape executable missions, objectives and choices. Edits are part of your adventure draft: save, check and rebuild to play them.</p></div></div><div id="missionEditor"></div><details class="mission-ai" id="missionAI" open><summary>Generate missions with AI</summary>${assistant('quests')}</details>`;}

function reviewHtml(r){if(!r)return '<p class="muted">Check the adventure to verify room reachability, quest targets, branches and prerequisites.</p>';return `<div class="notice ${r.errors.length?'validation-error':''}"><strong>${r.errors.length?r.errors.length+' issue(s) to resolve before building':'Adventure structure is ready to compile'}</strong>${r.errors.length?`<ul class="issues">${r.errors.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}</div>${r.warnings.length?`<details open><summary>${r.warnings.length} authoring note(s)</summary><ul class="issues">${r.warnings.map(x=>`<li>${E(x)}</li>`).join('')}</ul></details>`:''}`;}
function publish(){return `<div class="section-head"><div><h2>A complete module, ready to share.</h2><p class="muted">Compile the world and story into an ordinary NWN module with editable Aurora resources.</p></div><button data-action="build" class="primary">Build adventure</button></div><div class="author-grid review-page"><div><div class="card"><h3>Adventure check</h3><div id="reviewResult">${reviewHtml(report)}</div><button data-action="check">Check again</button></div><div class="card"><h3>Export settings</h3>${field('Module filename','module_name')}${field('Include optional live AI conversations','ai_conversations','checkbox')}<p class="standalone">✓ The main story, authored conversations, quests, puzzles, combat and endings run locally without Studio or an API key.</p><p class="hint">For live AI, extract the complete share ZIP and run Start Role Weaver.cmd. Keep the service window open, then start NWN separately and load the module. Players use their own API key; ordinary gameplay and authoring-time generated content also work offline.</p><div id="buildResult"></div></div><div class="card"><h3>Shareable builds</h3><div id="buildList">Loading builds…</div></div><div class="card"><h3>Your story at a glance</h3><p class="storyline-preview">${E(project.summary)}</p><h3>Quest paths</h3>${project.quests.map(q=>`<p><strong>${E(q.name)}</strong> ${q.optional?'<span class="pill">Optional</span>':''}<br><span class="hint">${questSummary(q)}</span></p>`).join('')}<h3>World</h3>${project.areas.map(a=>`<p>${E(a.name)} · ${E(app.authoring_catalog.area_types[a.type])} · ${a.width*10} × ${a.height*10} m<br><span class="hint">${a.rooms.map(r=>E(r.name)).join(' · ')}</span></p>`).join('')}</div></div><aside><div class="card accent"><h3>What players receive</h3><ol class="steps"><li>A standard <code>.mod</code> containing the complete adventure.</li><li>Install the module and included HAKs, or use Start Role Weaver.cmd in the extracted adventure package.</li><li>Start a new single-player game.</li><li>Play through the story using the native game.</li></ol><p class="hint">The share ZIP also includes instructions, the authoring project, native source resources and validation results.</p></div><div class="card"><h3>Continue in Aurora</h3><p class="muted">Open the exported module in Aurora to refine terrain, object placement, scripts and dialogue.</p><p class="hint">Keep Aurora edits in a separate copy. Rebuilding uses this project’s design, so Aurora changes are not automatically imported back.</p></div><div class="note">Compilation and graph checks run here. Opening in Aurora and testing the adventure in NWN remain the final author playtest.</div></aside></div>`;}
function settings(){return `<div id="providerSetup"></div><details class="card"><summary>Local NWN folders and compiler</summary><p class="hint">These paths are separate from your AI provider and model choices.</p>${['content_root','game_root','user_dir','compiler'].map(k=>`<label class="field"><span>${E({content_root:'Custom NWN content folder',game_root:'NWN installation folder',user_dir:'NWN user folder',compiler:'NWScript compiler'}[k])}</span><input data-setting="${k}" value="${E(app.settings[k])}"></label>`).join('')}<button data-action="settings" class="primary">Save local paths</button></details>${project?customContentPanel():''}`;}
function bindProviderSetup(){if($('#providerSetup'))AISetup.mount($('#providerSetup'),{state:app,api,onState:state=>{app=state;}});}

function render(){missionController?.destroy();missionController=null;analysisController?.destroy();analysisController=null;if(page==='publish'&&(!project||project.design_mode==='area'))page='analyser';if(page==='analyser'){syncNavigation();$('#projectTitle').textContent='Module Conversion';$('#saveState').textContent=dirty?'Unsaved project preserved':'Import & convert';['#saveProject','#deleteProject','#reviewProject'].forEach(s=>$(s).disabled=true);$('#stats').innerHTML='';analysisController=ModuleAnalyser.mount($('#workspace'),api,()=>app);return;}if(!project){emptyWorkspace();return;}if(project?.design_mode==='area'&&['brief','quests'].includes(page))page='world';renderHeader();const views={brief,world,encounters,cast,companions,behaviors,quests,publish,settings,guardrails:guardrailsPanel};$('#workspace').innerHTML=views[page]();bind();if(page==='publish')builds();if(page==='guardrails')loadUsage();if(page==='settings')bindProviderSetup();}
function set(path,v){const parts=path.split('.');let obj=project;for(const k of parts.slice(0,-1))obj=obj[k];obj[parts.at(-1)]=v;}
function bind(){bindSafety();
 if(page==='quests'&&$('#missionEditor'))missionController=MissionEditor.mount($('#missionEditor'),{getProject:()=>project,onChange:()=>{change();renderHeader();},onNotice:notify,onCheck:async()=>{const checked=await api('/api/author/review',{project});report=checked;return checked;},onGenerate:()=>{const panel=$('#missionAI');panel.open=true;$('#aiDirection').focus();panel.scrollIntoView({behavior:'smooth',block:'start'});}});
 bindAreaSections();
 bindDesign();
 bindPresets();
 if($('#floorplanUpload'))$('#floorplanUpload').onchange=e=>task(null,async()=>{const target=area(),refs=target.references||(target.references=[]);if(refs.length+e.target.files.length>3)throw Error('Use at most three images per area.');const additions=[];for(const file of e.target.files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2000000)throw Error('Choose PNG, JPEG or WebP images up to 2 MB.');const data_url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});additions.push({name:file.name.slice(0,120),notes:'',data_url});}refs.push(...additions);change();render();});
 if($('#assetSearch')){bindAssetCatalog();}
 document.querySelectorAll('[data-content-pack]').forEach(el=>el.onchange=()=>{project.custom_packs=project.custom_packs||[];const pack=assetLibrary.packs.find(p=>p.pack===el.dataset.contentPack);if(!el.checked){const ids=new Set((project.custom_assets||[]).filter(a=>a.pack===pack.pack).map(a=>a.id));if((project.custom_placements||[]).some(f=>ids.has(f.asset_id))){el.checked=true;notify('Remove this pack’s placed furnishings before removing its dependency.',true);return;}if(!confirmRemoval(pack.label||pack.pack,'This removes the pack dependency and its unused asset selections from this project.')){el.checked=true;return;}project.custom_assets=(project.custom_assets||[]).filter(a=>a.pack!==pack.pack);}project.custom_packs=project.custom_packs.filter(p=>p.pack!==pack.pack);if(el.checked)project.custom_packs.push({pack:pack.pack,sha256:pack.sha256});change();});
document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{const old=value(el.dataset.field);set(el.dataset.field,el.type==='checkbox'?el.checked:typeof old==='number'?Number(el.value):el.value);if(/^quests\.\d+\.steps\.\d+\.kind$/.test(el.dataset.field)){const target=value(el.dataset.field.replace(/\.kind$/,''));target.choices=el.value==='choice'?[{label:'First choice',next:'',text:''},{label:'Second choice',next:'',text:''}]:[];if(el.value==='choice')target.next='';}if(/^areas\.\d+\.type$/.test(el.dataset.field))reconcileAreaLook(value(el.dataset.field.replace(/\.type$/,'')));change();if(el.dataset.field==='title')$('#projectTitle').textContent=project.title;if(/\.merchant\.stock\.\d+\.item$/.test(el.dataset.field)){set(el.dataset.field.replace(/\.item$/,'.price'),app.authoring_catalog.merchandise[el.value].price);render();}if(/\.merchant\.(enabled|haggle_enabled|interface)$/.test(el.dataset.field))render();if(el.dataset.field.endsWith('.companion.recruitable'))render();if(/^companions\.templates\.\d+\.kind$/.test(el.dataset.field))set(el.dataset.field.replace(/\.kind$/,'.familiar_type'),-1);if(el.tagName==='SELECT'&&(/\.kind$/.test(el.dataset.field)||el.dataset.field.endsWith('.type')))render();}));document.querySelectorAll('[data-lines]').forEach(el=>el.oninput=()=>{set(el.dataset.lines,el.value.split('\n').filter(x=>x.trim()));change();});document.querySelectorAll('[data-multi]').forEach(el=>el.onchange=()=>{set(el.dataset.multi,[...el.selectedOptions].map(o=>o.value));change();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>task(b,()=>action(b.dataset.action)));
 document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{areaIndex=Number(b.dataset.area);roomIndex=0;render();});
 document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{roomIndex=Number(b.dataset.room??b.dataset.roomMap);render();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const [path,index]=b.dataset.remove.split(':'),item=value(path)[Number(index)],label=typeof item==='string'?item:item?.name||item?.topic||item?.label||item?.item||'this '+path.split('.').at(-1)+' entry';if(!confirmRemoval(label))return;value(path).splice(Number(index),1);change();render();});
 document.querySelectorAll('[data-route-up]').forEach(b=>b.onclick=()=>{const route=project.npcs[npcIndex].behavior.route,i=Number(b.dataset.routeUp);if(i>0){[route[i-1],route[i]]=[route[i],route[i-1]];change();render();}});
 document.querySelectorAll('[data-add-choice]').forEach(b=>b.onclick=()=>{project.quests[questIndex].steps[Number(b.dataset.addChoice)].choices.push({label:'New choice',next:'',text:''});change();render();});
 if($('#templateSelect'))$('#templateSelect').onchange=e=>{templateIndex=Number(e.target.value);render();};
 if($('#npcSelect'))$('#npcSelect').onchange=e=>{npcIndex=Number(e.target.value);render();};if($('#questSelect'))$('#questSelect').onchange=e=>{questIndex=Number(e.target.value);render();};
}
function addNPC(){const ident=id('person_');project.npcs.push({id:ident,name:'New character',alias:ident,role:'Supporting character',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',appearance:'man',ai_enabled:true,personality:'',knowledge:'',secret:'',reveal_after:'',motivation:'',game_notes:'',greeting:'Greetings, traveler.',dialogue:[],merchant:clone(app.authoring_catalog.merchant_defaults),companion:clone(app.authoring_catalog.npc_companion_defaults),behavior:clone(app.authoring_catalog.behavior_defaults)});npcIndex=project.npcs.length-1;}
async function action(name){
 const removing=removalAction(name);if(removing&&!confirmRemoval(removing,name.startsWith('key_remove_')?'This removes the saved credential from this computer. Environment keys are unchanged.':undefined))return;
 if(await designAction(name))return;
 if(name==='openAurora'){if(generating)throw Error('Wait for generation, then apply the proposal before opening Aurora.');const result=await api('/api/author/open-aurora',{project,area_id:area()?.id||''});if($('#auroraResult'))$('#auroraResult').innerHTML=`<div class="card"><strong>Aurora launch requested</strong><p>In Aurora, open Areas → ${E(result.area)} (${E(result.area_id)}).</p><p>Editable copy: <code>${E(result.module)}</code></p><p class="hint">Save your Aurora changes in this copy. Studio builds will not overwrite it.</p></div>`;notify('Aurora launch requested. Select '+result.area+' in its Areas tree.');return;}

 if(name.startsWith('key_save_')||name.startsWith('key_remove_')){const provider=name.split('_').at(-1),remove=name.startsWith('key_remove_'),input=$('#key_'+provider);try{await api('/api/credentials',{provider,remove,key:remove?undefined:input.value});app=await api('/api/state');if($('#loadExample'))$('#loadExample').disabled=!app.bundled_example;render();notify(remove?'Saved key removed.':'Key saved securely for this Windows user.');}finally{input.value='';}return;}
 if(name==='scanContent'){assetLibrary=await api('/api/assets/scan',{path:$('#contentPath').value});render();notify('Content catalog updated. All scanned placeables are now available to AI generation. Select supporting packs if needed.');return;}
 if(name==='addCustomAsset'){const asset=assetLibrary.assets.find(a=>a.id===$('#customAsset').value);if(!asset)throw Error('Choose a custom asset.');const room=selectedRoom()?.id||roomOptions()[0]?.[0];if(!room)throw Error('Create a room first.');project.custom_assets=project.custom_assets||[];if(!project.custom_assets.some(a=>a.id===asset.id))project.custom_assets.push(clone(asset));project.custom_placements=project.custom_placements||[];project.custom_placements.push({id:id('custom_'),name:asset.name.slice(0,100),room,asset_id:asset.id,placement:'north',description:''});const detail=await api('/api/assets/detail',{id:asset.id});if(detail.bounds){project.asset_geometry=project.asset_geometry||{};project.asset_geometry[asset.id]=detail.bounds;}project.custom_packs=project.custom_packs||[];if(asset.pack!=='builtin'&&!project.custom_packs.some(p=>p.pack===asset.pack))project.custom_packs.push({pack:asset.pack,sha256:asset.sha256});change();render();return;}
 if(name.startsWith('remove_reference_')){area().references.splice(Number(name.split('_').at(-1)),1);change();render();return;}
 if(name.startsWith('remove_custom_')){project.custom_placements.splice(Number(name.split('_').at(-1)),1);change();render();return;}

 if(name==='generate'||name==='generateArea'||name==='generateSelectedFloorplan'||name.startsWith('generateFloorplan_')){
  if(generating)throw Error('A proposal is already being generated.');const reference_index=name==='generateSelectedFloorplan'?Number($('#generationFloorplan').value):name.startsWith('generateFloorplan_')?Number(name.split('_').at(-1)):undefined;const scope=name==='generateArea'||reference_index!==undefined?'area':$('#aiScope').value,instruction=$('#aiDirection').value.trim()||'Use the supplied storyline and design notes to create coherent, playable content for the selected scope.';generating=true;$('#busy').hidden=false;['#projectSelect','#newProject','#importProject','#deleteProject'].forEach(s=>$(s).disabled=true);
  try{proposal=await api('/api/author/generate',{project,instruction,scope,area_id:area()?.id||'',reference_index});proposal.scope=scope;showProposal();}finally{generating=false;$('#busy').hidden=true;['#projectSelect','#newProject','#importProject','#deleteProject'].forEach(s=>$(s).disabled=false);}
 }
 if(name==='undoAI'&&previousDraft){project=previousDraft;previousDraft=null;change();render();}
 if(name==='addArea'){const ident=id('area_');project.areas.push({id:ident,name:'New area',type:'dungeon',width:14,height:12,room_count:2,description:'',lighting:'cold',rooms:[]});areaIndex=project.areas.length-1;roomIndex=0;change();render();}
 if(name==='arrange'){const r=await api('/api/author/arrange',{project,area_id:area().id});project=r.project;report=r.review;dirty=true;roomIndex=0;render();notify('Room layout generated. Edit the rooms and connect their exits.');}
 if(name==='preview'){report=await api('/api/author/review',{project});render();if(report.errors.length)notify(report.errors.slice(0,5).join('\n'),true);else notify('Corridors routed and adventure connections checked.');}
 if(name==='connectRooms'){autoConnect();change();report=await api('/api/author/review',{project});render();notify('Room corridors added. Review exit sides and the preview.');}
 if(name==='addRoom'){const a=area();const ident=id('room_');a.rooms.push({id:ident,name:'New room',x:1,y:1,width:3,height:3,description:'',purpose:'Exploration'});if(a.geometry)a.rooms.at(-1).interior={width_m:30,depth_m:30};a.room_count=a.rooms.length;roomIndex=a.rooms.length-1;change();render();notify('Place the new room or regenerate the layout before building.');}
 if(name==='deleteRoom'){area().rooms.splice(roomIndex,1);area().room_count=Math.max(1,area().rooms.length);roomIndex=0;change();render();notify('Room removed. Check connections and content references before building.');}
 if(name==='deleteArea'){project.areas.splice(areaIndex,1);areaIndex=roomIndex=0;change();render();}
 if(name==='addConnection'){const from=selectedRoom()?.id||roomOptions()[0]?.[0]||'',to=roomOptions().find(([id])=>id!==from)?.[0]||'';project.connections.push({id:id('link_'),name:'New passage',from_room:from,to_room:to,from_side:'east',to_side:'west',kind:area()?.rooms.some(r=>r.id===to)?'corridor':'exit',two_way:true,requires_quest:''});change();render();}
 if(name==='addEncounter'){project.encounters.push({id:id('enc_'),name:'New encounter',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',kind:'combat',description:'',creature:'goblin',count:1,maximum:3,scale:false,after_quest:'',prompt:'',options:[],answer:0,success:'',failure:'',gold:0,xp:0});change();render();}
 if(name==='addItem'){project.items.push({id:id('item_'),name:'Quest object',description:'',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',container:'',kind:'quest_token',quantity:1});change();render();}
 if(name==='roomDesign'){proposal=await api('/api/author/room-design',{project,room_id:$('#designRoom').value,style:$('#designStyle').value});showProposal();}
 if(name==='addFurniture'){project.furnishings.push({id:id('prop_'),name:'Supply crate',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',description:'',kind:'crate',placement:'north'});change();render();}
 if(name==='addNPC'){addNPC();change();render();}
 if(name==='deleteNPC'){project.npcs.splice(npcIndex,1);npcIndex=0;change();render();}
 if(name==='addPatrolStop'){const n=project.npcs[npcIndex];if(n.behavior.route.length>=16)throw Error('Use at most 16 patrol stops.');n.behavior.route.push(n.room);change();render();}
 if(name==='companionSettings'){page='companions';render();}
 if(name==='applyAIDefaults'){
  if(!confirm('Enable AI conversations and social chat for every character, allow all social partners, and enable companion movement, storage and NPC visits in this draft? Existing opt-outs will be replaced. Rebuild to use these changes in NWN.'))return;
  project.ai_conversations=true;project.ambient.social=true;Object.assign(project.companions,{enabled:true,familiars:true,summons:true});
  for(const n of project.npcs){n.ai_enabled=true;Object.assign(n.behavior,{social_enabled:true,accept_visits:true,partners:[]});Object.assign(n.companion,{movement:true,inventory:true,inspect_containers:true,social_visits:true});}
  for(const t of project.companions.templates)Object.assign(t,{ai_enabled:true,movement:true,inventory:true,inspect_containers:true,social_visits:true});
  change();render();notify('Defaults applied to this draft. Save and rebuild before playing.');return;
 }
 if(name==='addCompanionTemplate'){const t=clone(app.authoring_catalog.companion_defaults.templates.find(t=>t.kind==='summon'));t.id=id('cp_');t.name='Custom summoned companion';t.blueprints=[id('creature_')];project.companions.templates.push(t);templateIndex=project.companions.templates.length-1;change();render();}
 if(name==='addStock'){const m=project.npcs[npcIndex].merchant;const item=Object.keys(app.authoring_catalog.merchandise).find(k=>!m.stock.some(s=>s.item===k));if(!item)throw Error('All supported goods have stock lines.');m.stock.push({item,quantity:1,price:app.authoring_catalog.merchandise[item].price});change();render();}
 if(name==='addTopic'){project.npcs[npcIndex].dialogue.push({topic:'Tell me more.',text:'',after_quest:''});change();render();}
 if(name==='addQuest'){project.quests.push({id:id('quest_'),name:'New quest',description:'',start_npc:'',completion:'The quest is complete.',optional:false,requires:[],gold:0,xp:100,steps:[]});questIndex=project.quests.length-1;change();render();}
 if(name==='deleteQuest'){project.quests.splice(questIndex,1);questIndex=0;change();render();}
 if(name==='addStep'){const q=project.quests[questIndex],ident=id('objective_');if(q.steps.length&&q.steps.at(-1).kind!=='choice'&&!q.steps.at(-1).next)q.steps.at(-1).next=ident;q.steps.push({id:ident,name:'New objective',description:'',kind:'talk',target:project.npcs[0]?.id||'',next:'',consume:false,choices:[]});change();render();}
 if(name==='check'){report=await api('/api/author/review',{project});page='publish';render();}
 if(name==='build'){report=await api('/api/author/review',{project});if(report.errors.length){render();throw Error('Resolve the adventure check issues before building.');}$('#reviewResult').innerHTML=reviewHtml(report);const build=await api('/api/build',{project});dirty=false;renderHeader();$('#buildResult').innerHTML=`<div class="build-download"><strong>Native adventure compiled</strong><p>${build.areas} areas · ${build.rooms} rooms · ${build.quests} quests · ${build.compiled_scripts} compiled scripts</p><a href="/download?build=${build.build_id}&kind=zip">Download share / Aurora ZIP</a><a href="/download?build=${build.build_id}&kind=mod">Download .mod</a><button id="installBuild">Install for my playtest</button><button id="playBuild" class="primary">Play in NWN</button><p class="hint">Ready for your NWN and Aurora checks.</p></div>`;$('#installBuild').onclick=e=>task(e.target,()=>install(build.build_id));$('#playBuild').onclick=e=>task(e.target,()=>play(build.build_id));await builds();}
 if(name==='settings'){const settings={};document.querySelectorAll('[data-setting]').forEach(el=>settings[el.dataset.setting]=el.value);await api('/api/settings',settings);app=await api('/api/state');if($('#loadExample'))$('#loadExample').disabled=!app.bundled_example;render();notify('Local paths saved.');}
}
function autoConnect(){const a=area();if(a.rooms.length<2)throw Error('Add or generate at least two rooms.');const groups=new Map(a.rooms.map(r=>[r.id,r.id]));const root=id=>{while(groups.get(id)!==id)id=groups.get(id);return id;};const used=new Set();project.connections.forEach(c=>{used.add(c.from_room+':'+c.from_side);used.add(c.to_room+':'+c.to_side);if(groups.has(c.from_room)&&groups.has(c.to_room))groups.set(root(c.from_room),root(c.to_room));});const pairs=[];for(let i=0;i<a.rooms.length;i++)for(let j=i+1;j<a.rooms.length;j++){const r=a.rooms[i],s=a.rooms[j],dx=s.x+s.width/2-r.x-r.width/2,dy=s.y+s.height/2-r.y-r.height/2;const sides=Math.abs(dx)>=Math.abs(dy)?dx>=0?['east','west']:['west','east']:dy>=0?['north','south']:['south','north'];pairs.push({r,s,sides,d:Math.abs(dx)+Math.abs(dy)});}for(const {r,s,sides} of pairs.sort((a,b)=>a.d-b.d)){if(root(r.id)===root(s.id)||used.has(r.id+':'+sides[0])||used.has(s.id+':'+sides[1]))continue;project.connections.push({id:id('passage_'),name:r.name+' to '+s.name,from_room:r.id,to_room:s.id,from_side:sides[0],to_side:sides[1],kind:'corridor',two_way:true,requires_quest:''});used.add(r.id+':'+sides[0]);used.add(s.id+':'+sides[1]);groups.set(root(r.id),root(s.id));}if(new Set(a.rooms.map(r=>root(r.id))).size>1)notify('Some rooms still need a manually positioned connection.',true);}
async function builds(){
 const projectId=project?.id,{builds:all}=await api('/api/builds'),list=$('#buildList');if(!list||project?.id!==projectId)return;
 const visible=all.filter(b=>b.project_id===projectId).reverse();
 list.innerHTML=visible.map((b,i)=>`<div class="build"><strong>${E(b.title)}</strong> ${i===0?'<span class="pill">Latest export</span>':''}<p>${E(b.module)} · ${b.areas} areas · ${b.rooms||'?'} rooms · ${b.quests||'?'} quests${b.optional_live_ai?' · optional live AI':''}<br><small class="hint">Build ${E(b.build_id)}</small></p><div class="actions"><a href="/download?build=${encodeURIComponent(b.build_id)}&kind=zip">Share / Aurora ZIP</a><a href="/download?build=${encodeURIComponent(b.build_id)}&kind=mod">Module</a><a href="/download?build=${encodeURIComponent(b.build_id)}&kind=project">Project</a><button data-install="${E(b.build_id)}" class="quiet">Install for playtest</button><button data-play="${E(b.build_id)}" class="primary">Play in NWN</button><button data-delete-build="${E(b.build_id)}" class="quiet danger">Delete build</button></div></div>`).join('')||'<p class="muted">No builds yet. Check the adventure, then compile it.</p>';
 list.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>task(b,()=>play(b.dataset.play)));
 list.querySelectorAll('[data-install]').forEach(b=>b.onclick=()=>task(b,()=>install(b.dataset.install)));
 list.querySelectorAll('[data-delete-build]').forEach(button=>button.onclick=()=>deleteBuild(visible.find(b=>b.build_id===button.dataset.deleteBuild),button));
}
async function deleteBuild(build,button){
 if(!build||!confirmRemoval('build '+build.module+' ('+build.build_id+')','This permanently deletes this export’s module, share ZIP and generated source files from Studio. Your saved project, installed copies and AI adventure profile are kept.'))return;
 await task(button,async()=>{
  await api('/api/build/delete',{build_id:build.build_id,confirm:true});
  const result=$('#buildResult');if(result?.querySelector('a[href="/download?build='+build.build_id+'&kind=mod"]'))result.innerHTML='';
  await builds();notify('Build deleted. Your project and installed adventure are preserved.');
 });
}
async function install(build_id){const r=await api('/api/install',{build_id});notify('Installed: '+r.installed+(r.backup?'\nPrevious copy backed up.':''));}
function modal(html,apply=false){$('#modalContent').innerHTML=html;$('#applyProposal').hidden=!apply;$('#modal').showModal();}
function showProposal(){const p=proposal.proposal;modal(`<h2>Apply the generated design</h2><p><strong>The generated result is not in your draft yet. Click Apply proposal below before building or opening Aurora.</strong></p><button id="discardGeneratedProposal" class="quiet">Discard generated proposal</button><p class="muted">Nothing has been applied yet. Compare the story, world and quest paths, then apply the proposal to your editable draft.</p><div class="metric-row">${['areas','npcs','encounters','quests','furnishings'].map(k=>`<span>${project[k].length} → ${p[k].length} ${k}</span>`).join('')}</div><h3 class="after-card">${E(p.title)}</h3><p class="storyline-preview">${E(p.summary)}</p><div class="preview-list"><div><h3>World</h3><ul>${p.areas.map(a=>`<li>${E(a.name)} · ${a.width}×${a.height} tiles · ${a.rooms.length} rooms</li>`).join('')}</ul><h3>Characters</h3><ul>${p.npcs.map(n=>`<li>${E(n.name)} — ${E(n.role)}</li>`).join('')}</ul></div><div><h3>Quests</h3><ul>${p.quests.map(q=>`<li>${E(q.name)}<br><small>${questSummary(q)}</small></li>`).join('')}</ul></div></div>${reviewHtml(proposal.review)}<details><summary>Inspect the complete proposal</summary><pre>${E(JSON.stringify(p,null,2))}</pre></details>`,true);$('#discardGeneratedProposal').onclick=()=>{if(!confirmRemoval('this generated proposal','The unapplied generated result will be discarded. Your current draft stays as it is.'))return;proposal=null;$('#modal').close();};}
$('#saveProject').onclick=e=>task(e.target,save);$('#deleteProject').onclick=requestProjectDeletion;$('#guardrailsButton').onclick=()=>{page='guardrails';render();};$('#reviewProject').onclick=e=>task(e.target,()=>action('check'));$('#settingsButton').onclick=()=>{page='settings';render();};document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#projectSelect').onchange=async e=>{const ident=e.target.value;await task(null,async()=>{if(dirty)await save();await load(ident);$('#projectSelect').value=ident;});};$('#closeModal').onclick=()=>$('#modal').close();$('#applyProposal').onclick=()=>{const selectedAreaId=area()?.id,showMissions=['quests','adventure'].includes(proposal.scope);previousDraft=clone(project);project=proposal.proposal;dirty=true;report=proposal.review;areaIndex=Math.max(0,project.areas.findIndex(a=>a.id===selectedAreaId));roomIndex=npcIndex=questIndex=templateIndex=0;proposal=null;if(showMissions&&project.design_mode!=='area')page='quests';$('#modal').close();render();scrollWorkspaceTop();notify(showMissions?'AI missions applied. Review and edit them on the mission map, then save.':'AI proposal applied to the draft. Edit and save when ready.');};
$('#newProject').onclick=()=>{modal('<h2>Create a project</h2><label class="field"><span>Project type</span><select id="newMode"><option value="area">Standalone area workspace</option><option value="adventure">Adventure</option></select></label><p class="muted">Design areas independently, then copy them into an adventure when ready.</p><label class="field"><span>Project title</span><input id="newTitle" value="Untitled area"></label><label class="field"><span>Project ID · lowercase letters, numbers and underscores</span><input id="newId" placeholder="my_adventure"></label><button id="createProject" class="primary">Create project</button>');$('#createProject').onclick=e=>task(e.target,async()=>{if(dirty)await save();const r=await api('/api/project/new',{id:$('#newId').value,title:$('#newTitle').value,design_mode:$('#newMode').value});project=r.project;dirty=false;report=null;previousDraft=null;proposal=null;areaIndex=roomIndex=0;page=project.design_mode==='area'?'world':'brief';app.projects=(await api('/api/state')).projects;projectList();$('#modal').close();render();});};$('#importProject').onclick=()=>$('#importFile').click();$('#importFile').onchange=e=>task(null,async()=>{const f=e.target.files[0];if(!f)return;const document=JSON.parse(await f.text());if((document.project||document).schema_version!==2)throw Error('Choose a Module Studio format-2 project. The previous courier template remains available separately.');if(dirty)await save();project=(await api('/api/project/import',{document})).project;dirty=false;report=null;app.projects=(await api('/api/state')).projects;projectList();render();notify('Adventure imported. A previous authoring copy, if present, was backed up.');e.target.value='';});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{app=await api('/api/state');if($('#studioVersion'))$('#studioVersion').textContent='AUTHORING TOOLSET · '+app.version;if($('#loadExample'))$('#loadExample').disabled=!app.bundled_example;assetLibrary=await api('/api/assets/list',{});projectList();const first=app.projects.find(p=>p.schema_version===2);if(first)await load(first.id);else{project=null;render();}const requestedView=new URLSearchParams(window.location.search).get('view');if(['guardrails','settings','analyser','conversion','quests'].includes(requestedView)){page=requestedView==='conversion'?'analyser':requestedView;render();}}catch(e){$('#workspace').textContent='Unable to open Module Studio: '+e.message;}})();

async function play(build_id){
 if(dirty&&!confirm('Launch this exported build? Unsaved edits will not be included. Cancel to save and rebuild first.'))return;
 const result=await api('/api/play',{build_id});notify('NWN started for '+result.module+'. Choose your character to begin. Keep the Role Weaver service running.');
}
window.RoleWeaverBeforeUpdate=async()=>{if(dirty)throw Error('Save your project before installing the update.');};
$('#loadExample').onclick=e=>task(e.target,async()=>{
 if(!confirm('Load the included Emberseal of Briarwatch example? Your current draft will be saved first. An existing Emberseal draft will be backed up before replacing it with the bundled version. Other projects are preserved.'))return;
 if(dirty)await save();
 const result=await api('/api/example/load',{confirm:true});
 app=await api('/api/state');projectList();page='brief';await load(result.project.id);
 notify('Emberseal loaded. Open Build & share to download it or play in NWN.'+(result.backup?' Your earlier draft was backed up.':''));
});
